<script setup lang="ts">import{onBeforeUnmount,ref}from'vue';import{client,errorMessage,requireData}from'../../shared/api/client';const emit=defineEmits<{ready:[]}>();const error=ref('');const busy=ref(false);let worker:Worker|undefined;async function prove(){busy.value=true;error.value='';try{const value=requireData(await client.GET('/api/public/pow'));const url=new URL('./pow-worker.ts',import.meta.url);worker=new Worker(url,{type:'module'});const nonce=await new Promise<string>((resolve,reject)=>{worker!.onmessage=event=>resolve(event.data);worker!.onerror=event=>reject(new Error(event.message));worker!.postMessage(value)});requireData(await client.POST('/api/public/session',{body:{turnstileToken:'',powChallenge:value.challenge,powNonce:nonce}}));emit('ready')}catch(cause){error.value=errorMessage(cause)}finally{busy.value=false;worker?.terminate()}}onBeforeUnmount(()=>worker?.terminate())</script>
<template><section class="rounded-card border border-border p-4"><p>为保护公开问答，需要完成一次本地工作量证明。计算只在浏览器中进行。</p><button class="nw-button mt-3" :disabled="busy" @click="prove">{{ busy?'正在验证…':'开始验证' }}</button><p v-if="error" class="text-danger">{{ error }}</p></section></template>
